import pandas as pd
import pytz
from datetime import datetime
from random import randint, seed as set_seed

def task_func(
    utc_datetime,
    cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney'],
    weather_conditions=['Sunny', 'Cloudy', 'Rainy', 'Snowy', 'Stormy'],
    timezones={
        'New York': 'America/New_York',
        'London': 'Europe/London',
        'Beijing': 'Asia/Shanghai',
        'Tokyo': 'Asia/Tokyo',
        'Sydney': 'Australia/Sydney'
    },
    seed=42
):
    # Validate utc_datetime
    if not isinstance(utc_datetime, datetime):
        raise ValueError("utc_datetime must be a datetime object")

    # Validate seed
    if not isinstance(seed, int):
        raise ValueError("seed must be an integer")

    # Validate cities
    if not isinstance(cities, (list, tuple)):
        raise ValueError("cities must be a list or tuple of strings")
    if any(not isinstance(city, str) for city in cities):
        raise ValueError("cities must be a list or tuple of strings")

    # Validate weather_conditions
    if not isinstance(weather_conditions, (list, tuple)) or len(weather_conditions) == 0:
        raise ValueError("weather_conditions must be a non-empty list or tuple of strings")
    if any(not isinstance(condition, str) for condition in weather_conditions):
        raise ValueError("weather_conditions must be a non-empty list or tuple of strings")

    # Validate timezones
    if not isinstance(timezones, dict):
        raise ValueError("timezones must be a dictionary mapping city names to timezone names")
    if any(not isinstance(k, str) or not isinstance(v, str) for k, v in timezones.items()):
        raise ValueError("timezones must be a dictionary mapping city names to timezone names")

    # Ensure all cities have timezone mappings and that the timezones are valid
    for city in cities:
        if city not in timezones:
            raise ValueError(f"Missing timezone for city: {city}")
        try:
            pytz.timezone(timezones[city])
        except Exception as exc:
            raise ValueError(f"Invalid timezone for city {city}: {timezones[city]}") from exc

    # Convert utc_datetime to a UTC-aware datetime
    if utc_datetime.tzinfo is None:
        utc_dt = pytz.UTC.localize(utc_datetime)
    else:
        utc_dt = utc_datetime.astimezone(pytz.UTC)

    # Deterministic weather selection
    set_seed(seed)

    rows = []
    for city in cities:
        tz = pytz.timezone(timezones[city])
        local_dt = utc_dt.astimezone(tz)
        weather = weather_conditions[randint(0, len(weather_conditions) - 1)]
        rows.append({
            'City': city,
            'Local Time': local_dt.strftime('%Y-%m-%d %H:%M:%S %Z'),
            'Weather Condition': weather
        })

    return pd.DataFrame(rows, columns=['City', 'Local Time', 'Weather Condition'])
